import React, { useState } from "react"
import { Button } from "@/components/atoms/rocksport-b2b/button"

const OtpVerification = ({ onVerify, onBack }) => {
  const [otp, setOtp] = useState(["", "", "", ""])

  const handleChange = (value, index) => {
    const updated = [...otp]
    updated[index] = value.slice(-1)
    setOtp(updated)
  }

  return (
    <div className="bg-baby-powder rounded-xl p-10 text-center space-y-6">
      <h2 className="text-xl font-semibold">OTP Verification</h2>

      <div className="flex justify-center gap-3">
        {otp.map((digit, i) => (
          <input
            key={i}
            value={digit}
            onChange={(e) => handleChange(e.target.value, i)}
            className="w-12 h-12 text-center border rounded-lg"
            maxLength={1}
          />
        ))}
      </div>

      <div className="flex justify-center gap-4">
        <Button variant="outlinePrimary" onClick={onBack}>
          Back
        </Button>
        <Button variant="fillPrimary" onClick={onVerify}>
          Verify
        </Button>
      </div>
    </div>
  )
}

export default OtpVerification